rately: it needs no monotonicity, no divergence, and no bracketing argument, and it is the weakest hypothesis the interpolation step can consume.",","+    "disclaims": "It does not prove the prize, and the hypothesis is not known for the centre column. It is true of any Bool sequence, and at M = N it degenerates to the excess bound itself, so its whole content is that the cut may be sparse. A neighbouring formulation is measured DEAD and must not be proposed: 'every block of some fixed length L is balanced to L / d' is unsatisfiable for the centre column, because long runs keep appearing — at L = 16 a block of 16 identical cells occurs at M = 22711, worst block excess 1.0000 (explorer/tessera2_blocks.mjs, N = 400000). No finite witness is possible.",","     "route": {","-      "tactics": "  have tb : ∀ r i : ℕ, (rowStep r).testBit i\n      = xor (decide (2 ≤ i) && r.testBit (i - 2))\n          ((decide (1 ≤ i) && r.testBit (i - 1)) || r.testBit i) := by\n    intro r i\n    have h4 : 4 * r = 2 ^ 2 * r := by norm_num\n    have h2 : 2 * r = 2 ^ 1 * r := by norm_num\n    unfold rowStep\n    rw [h4, h2, Nat.testBit_xor, Nat.testBit_or, Nat.testBit_two_pow_mul,\n      Nat.testBit_two_pow_mul]\n  have miff : ∀ a b m : ℕ, a % 2 ^ m = b % 2 ^ m ↔ ∀ i < m, a.testBit i = b.testBit i := by\n    intro a b m\n    constructor\n    · intro hh i hi\n      have := congrArg (fun z => z.testBit i) hh\n      simpa [Nat.testBit_mod_two_pow, hi] using this\n    · intro hh\n      apply Nat.eq_of_testBit_eq\n      intro i\n      rw [Nat.testBit_mod_two_pow, Nat.testBit_mod_two_pow]\n      by_cases hi : i < m\n      · simp [hi, hh i hi]\n      · simp [hi]\n  have hlow := (miff _ _ _).1 h\n  have hbit : ((rowStep x).testBit (n + 1) = (rowStep y).testBit (n + 1)) ↔\n      (x.testBit n = true ∨ x.testBit (n + 1) = y.testBit (n + 1)) := by\n    have h1 : decide (1 ≤ n + 1) = true := by simp\n    rw [tb, tb, show n + 1 - 1 = n by omega, hlow (n + 1 - 2) (by omega),\n      hlow n (by omega), h1, Bool.true_and]\n    generalize (decide (2 ≤ n + 1) && y.testBit (n + 1 - 2)) = a\n    generalize y.testBit n = b\n    generalize x.testBit (n + 1) = c\n    generalize y.testBit (n + 1) = d\n    cases a <;> cases b <;> cases c <;> cases d <;> decide\n  have hlow1 : ∀ i < n + 1, (rowStep x).testBit i = (rowStep y).testBit i := by\n    intro i hi\n    rw [tb, tb, hlow (i - 2) (by omega), hlow (i - 1) (by omega), hlow i (by omega)]\n  rw [miff, miff]\n  constructor\n  · intro hall\n    rcases (hbit.1 (hall (n + 1) (by omega))) with h1 | h1\n    · exact Or.inl h1\n    · refine Or.inr fun i hi => ?_\n      by_cases hi' : i < n + 1\n      · exact hlow i hi'\n      · have : i = n + 1 := by omega\n        subst this; exact h1\n  · intro hor i hi\n    by_cases hi' : i < n + 1\n    · exact hlow1 i hi'\n    · have : i = n + 1 := by omega\n      subst this\n      rw [hbit]\n      rcases hor with h1 | h1\n      · exact Or.inl h1\n      · exact Or.inr (h1 (n + 1) (by omega))",","-      "imports": ["Rule30.Basic", "Mathlib.Tactic"]","-    },","-    "witness": {","-      "expression": "(List.range 6).all fun n => (List.range 130).all fun x => (List.range 130).all fun y =>\n  !(decide (x % 2 ^ (n + 1) = y % 2 ^ (n + 1))) ||\n    decide ((rowStep x % 2 ^ (n + 2) = rowStep y % 2 ^ (n + 2)) ↔\n      (x.testBit n = true ∨ x % 2 ^ (n + 2) = y % 2 ^ (n + 2)))",","-      "imports": ["Rule30.Basic"],","-      "range": "n < 6, x < 130, y < 130, filtered on the hypothesis. Ran true. Reading the control bit at n+1 instead of n returns false."","+      "tactics": "  rw [centerColumn_density_tendsto_half_iff_excess]\n  intro ε hε\n  obtain ⟨d, hdgt⟩ := exists_nat_gt (3 / ε)\n  have hpos : (0 : ℝ) < (d : ℝ) := lt_trans (by positivity) hdgt\n  have hdpos : 0 < d := by exact_mod_cast hpos\n  obtain ⟨N₀, hN₀⟩ := h d hdpos\n  refine ⟨N₀, fun N hN => ?_⟩\n  obtain ⟨M, hMN, hgap, he1, he2⟩ := hN₀ N hN\n  obtain ⟨hs1, hs2⟩ := centerColumnCount_sandwich M N hMN\n  obtain ⟨g, rfl⟩ := Nat.exists_eq_add_of_le